/**
 * Step 10: the faithfulness metric, wired to something it can score.
 *
 * The verbatim-span check is a HARD GATE and this file is where it bites: any
 * fabricated quotation in the sample fails these tests, and `npm run build`
 * runs the suite. A fabricated quotation is not a quality regression to be
 * traded off — it is a false statement about what a safety document says,
 * attributed to that document, in front of someone deciding whether to notify
 * a regulator.
 *
 * The sample is generated by running real assessments over the seeded corpus
 * with model behaviours we control, so the harness scores the actual pipeline
 * rather than hand-written readings.
 */
import { describe, expect, it } from "vitest";
import { SEED_CHUNKS, SEED_DOCUMENTS } from "@/lib/fixtures/documents";
import {
  ChunkId,
  DocumentId,
  DrugId,
  type DocumentChunk,
  type NarrativePoint,
  type SuspectDrug,
} from "@/lib/schemas";
import { assessCase } from "@/lib/assess/assess";
import { verifyGeneration } from "@/lib/assess/verify";
import { documentsForDrug } from "@/lib/assess/scope";
import { messagesOf, type AiBinding } from "@/lib/assess/ai";
import {
  scoreFaithfulness,
  scoreNarrative,
  scoreNarrativeFaithfulness,
  scoreReading,
  unsupportedTerms,
  type ScoredNarrative,
  type ScoredReading,
} from "./faithfulness";

const DOC = DocumentId.parse("00000001-0000-4000-8000-000000000001");
const chunk = (id: string, text: string): DocumentChunk => ({
  id: ChunkId.parse(id),
  documentId: DOC,
  sourceType: "company",
  section: "4.8 Undesirable effects",
  ordinal: 1,
  text,
  charStart: 0,
  charEnd: text.length,
  tokenEstimate: Math.ceil(text.length / 4),
});

const CHUNK = chunk(
  "ccds#1",
  "Elevations in hepatic transaminases have been reported in approximately 2.1% of patients. Jaundice has been reported rarely.",
);

const reading = (over: Record<string, unknown>): ScoredReading => ({
  reading: {
    status: "read",
    chunkId: ChunkId.parse("ccds#1"),
    quotedSpan: "Jaundice has been reported rarely.",
    rationale: "The passage records jaundice as a rare event.",
    model: "@cf/meta/llama-3.1-8b-instruct",
    gatewayRequestId: "aig-1",
    generatedAt: "2026-08-26T10:00:00Z",
    ...over,
  },
  chunks: [CHUNK],
});

describe("the hard gate", () => {
  it("passes a span that occurs character for character", () => {
    expect(scoreReading(reading({}))).toHaveLength(0);
  });

  it("fails fatally on a fabricated span", () => {
    const failures = scoreReading(
      reading({ quotedSpan: "Fatal hepatic failure occurred in 3% of patients." }),
    );
    expect(failures.some((f) => f.kind === "span_not_in_chunk" && f.fatal)).toBe(true);
  });

  it("accepts a span that stops short, because that is still verbatim", () => {
    // Dropping the trailing full stop leaves a genuine substring of the
    // passage. The rule is "occurs in the chunk", not "is a whole sentence",
    // and a reviewer quoting half a sentence has still quoted the document.
    expect(
      scoreReading(reading({ quotedSpan: "Jaundice has been reported rarely" })),
    ).toHaveLength(0);
  });

  it("fails fatally on a span tidied up rather than copied", () => {
    // One word changed. Every character but that one is right, which is
    // exactly what makes this the dangerous case rather than the obvious one.
    const failures = scoreReading(
      reading({ quotedSpan: "Jaundice has been reported frequently." }),
    );
    expect(failures.some((f) => f.kind === "span_not_in_chunk" && f.fatal)).toBe(true);
  });

  it("fails fatally on re-punctuation, which reads as a faithful quote", () => {
    const failures = scoreReading(
      reading({ quotedSpan: "Jaundice has been reported, rarely." }),
    );
    expect(failures.some((f) => f.fatal)).toBe(true);
  });

  it("fails fatally when the cited chunk was never supplied", () => {
    const failures = scoreReading({
      ...reading({}),
      chunks: [chunk("ccds#9", "Something else entirely.")],
    });
    expect(failures.some((f) => f.kind === "chunk_not_supplied" && f.fatal)).toBe(true);
  });
});

describe("the rationale checks, which are scored and not gated", () => {
  it("catches a rationale that reaches a determination", () => {
    const failures = scoreReading(
      reading({ rationale: "This reaction is listed in the company document." }),
    );
    expect(failures.some((f) => f.kind === "rationale_determines")).toBe(true);
    expect(failures.every((f) => !f.fatal)).toBe(true);
  });

  it("catches a rationale that recommends", () => {
    const failures = scoreReading(
      reading({ rationale: "An expedited report is required here." }),
    );
    expect(failures.some((f) => f.kind === "rationale_determines" || f.kind === "rationale_recommends")).toBe(true);
  });

  it("catches a rationale asserting terms the passage never mentions", () => {
    const failures = scoreReading(
      reading({ rationale: "The passage describes renal impairment and seizures." }),
    );
    expect(failures.some((f) => f.kind === "rationale_unsupported_terms")).toBe(true);
  });

  it("accepts a paraphrase that stays inside the passage's own vocabulary", () => {
    expect(
      unsupportedTerms(
        "The passage records hepatic transaminase elevations in 2.1% of patients.",
        CHUNK.text,
      ),
    ).toHaveLength(0);
  });

  it("does not score a reading that made no claim", () => {
    const result = scoreFaithfulness([
      {
        reading: {
          status: "nothing_found",
          model: "m",
          gatewayRequestId: null,
          generatedAt: "2026-08-26T10:00:00Z",
        },
        chunks: [CHUNK],
      },
      {
        reading: {
          status: "unavailable",
          reason: "no binding",
          model: null,
          gatewayRequestId: null,
          attemptedAt: "2026-08-26T10:00:00Z",
        },
        chunks: [CHUNK],
      },
    ]);
    expect(result.checked).toBe(0);
    expect(result.failures).toHaveLength(0);
    // An honest 1: nothing was claimed, so nothing was unfaithful.
    expect(result.score).toBe(1);
  });
});

// ---------------------------------------------------------------------------
// The sample: real assessments over the seeded corpus.
// ---------------------------------------------------------------------------

const HEPALEX: SuspectDrug = {
  id: DrugId.parse("00000002-0000-4000-8000-000000000001"),
  reportedName: "Hepalex",
  activeSubstance: "hepalexin",
  role: "suspect",
  marketingStatus: "marketed",
  dose: null,
  route: null,
  indication: null,
  therapyStart: null,
  therapyEnd: null,
  dechallenge: null,
  rechallenge: null,
};

/** Reads the prompt and quotes its first sentence back — a faithful model. */
function faithfulBinding(): AiBinding {
  return {
    run: (_m, input) => {
      const user = messagesOf(input).find((x) => x.role === "user")?.content ?? "";
      const match = /<<<PASSAGE id="([^"]+)"[^\n]*\n([\s\S]*?)\nPASSAGE>>>/.exec(user);
      const sentence = /^[^.]+\./.exec(match?.[2] ?? "")?.[0] ?? "";
      if (match?.[1] === undefined || sentence === "") {
        return Promise.resolve({
          response: JSON.stringify({ found: false, chunkId: null, quotedSpan: null, rationale: null }),
        });
      }
      return Promise.resolve({
        response: JSON.stringify({
          found: true,
          chunkId: match[1],
          quotedSpan: sentence,
          rationale: null,
        }),
      });
    },
    aiGatewayLogId: "aig-eval",
  };
}

/** Quotes something that is not in any passage — the failure being gated. */
function fabricatingBinding(): AiBinding {
  return {
    run: (_m, input) => {
      const user = messagesOf(input).find((x) => x.role === "user")?.content ?? "";
      const id = /<<<PASSAGE id="([^"]+)"/.exec(user)?.[1] ?? "unknown";
      return Promise.resolve({
        response: JSON.stringify({
          found: true,
          chunkId: id,
          quotedSpan: "Fatal hepatic failure occurred in 3% of patients.",
          rationale: null,
        }),
      });
    },
    aiGatewayLogId: "aig-eval",
  };
}

const CASES = [
  { reaction: "liver failure, died", drug: HEPALEX },
  { reaction: "jaundice", drug: HEPALEX },
  { reaction: "yellow skin and eyes", drug: HEPALEX },
] as const;

async function sampleAssessments(binding: AiBinding): Promise<ScoredReading[]> {
  const samples: ScoredReading[] = [];
  for (const c of CASES) {
    const ids = documentsForDrug(SEED_DOCUMENTS, c.drug);
    const out = await assessCase({
      chunks: SEED_CHUNKS,
      documentIds: ids,
      reactionTerm: c.reaction,
      drugName: c.drug.reportedName,
      documentKind: "ccds",
      labelSetId: null,
      ai: { binding, reason: null, source: "http" as const },
      gateway: null,
      now: "2026-08-26T10:00:00Z",
      actor: "eval",
      target: "eval",
    });
    for (const finding of [out.listedness, out.expectedness]) {
      if (finding.state !== "grounded") continue;
      // The chunks the reading could cite are exactly the ones retrieved,
      // recovered here through the citations the finding carries.
      const chunks = SEED_CHUNKS.filter((ch) =>
        finding.citations.some((cit) => cit.chunkId === ch.id),
      );
      samples.push({ reading: finding.reading, chunks });
    }
  }
  return samples;
}

describe("scoring the real pipeline", () => {
  it("scores a faithful run clean, with something actually scored", async () => {
    const samples = await sampleAssessments(faithfulBinding());
    const result = scoreFaithfulness(samples);
    // The metric must have something to score — a harness that silently
    // measures an empty sample passes forever and means nothing.
    expect(result.checked).toBeGreaterThan(0);
    expect(result.fatalFailures).toHaveLength(0);
    expect(result.score).toBe(1);
  });

  it("HARD GATE: a fabricated quotation never survives to be scored", async () => {
    /*
      This is the belt-and-braces assertion, and it is worth being precise
      about what it proves. verify.ts rejects a fabricated span at generation
      time, so the pipeline degrades to `unavailable` and the eval never sees a
      `read` reading to fail. The gate below would catch one if it ever did.
      Both layers are asserted because a change that removed either should
      turn this file red.
    */
    const samples = await sampleAssessments(fabricatingBinding());
    for (const s of samples) {
      expect(s.reading.status).not.toBe("read");
    }
    const result = scoreFaithfulness(samples);
    expect(result.fatalFailures).toHaveLength(0);
    expect(result.checked).toBe(0);
  });

  it("HARD GATE: the gate itself fails the build on a fabricated span", () => {
    // If a fabricated reading ever did reach the eval — through a stored row,
    // a cache, a fixture — this is the assertion that fails.
    const result = scoreFaithfulness([
      reading({ quotedSpan: "Fatal hepatic failure occurred in 3% of patients." }),
    ]);
    expect(result.fatalFailures.length).toBeGreaterThan(0);
    expect(result.score).toBeLessThan(1);
  });
});

describe("the gate agrees with the check it guards", () => {
  const FENCED = "Hepatic <<<PASSAGE failure was seen in two subjects.";
  const fencedChunk = chunk("company#12", FENCED);

  it("accepts the span the runtime accepted, for a chunk containing the fence", () => {
    /*
      The runtime shows the model `sanitisePassage(text)`, so a faithful model
      copies the "[removed]" it was given. verifyGeneration accepts that. The
      eval used to compare against the RAW text and call the same span a
      fabricated quotation — failing the build on honest work.

      This test runs the real runtime check first and feeds its output to the
      gate, so the two can never drift apart again without going red.
    */
    const verified = verifyGeneration({
      raw: {
        found: true,
        chunkId: "company#12",
        quotedSpan: "Hepatic [removed] failure was seen in two subjects.",
        rationale: null,
      },
      chunks: [fencedChunk],
      model: "@cf/meta/llama-3.1-8b-instruct",
      gatewayRequestId: null,
      now: "2026-08-26T10:00:00Z",
    });
    expect(verified.ok).toBe(true);
    if (verified.ok) {
      expect(scoreReading({ reading: verified.reading, chunks: [fencedChunk] })).toHaveLength(0);
    }
  });

  it("still fails a span that occurs in neither the raw nor the sanitised text", () => {
    const failures = scoreReading({
      reading: {
        status: "read",
        chunkId: ChunkId.parse("company#12"),
        quotedSpan: "Fatal hepatic failure occurred in 3% of patients.",
        rationale: null,
        model: "m",
        gatewayRequestId: null,
        generatedAt: "2026-08-26T10:00:00Z",
      },
      chunks: [fencedChunk],
    });
    expect(failures.some((f) => f.kind === "span_not_in_chunk" && f.fatal)).toBe(true);
  });
});


// ---------------------------------------------------------------------------
// The narrative
// ---------------------------------------------------------------------------

describe("narrative faithfulness", () => {
  const A = chunk(
    "ccds#1",
    "Elevations in hepatic transaminases have been reported. Jaundice has been reported rarely.",
  );
  const B = chunk(
    "ccds#2",
    "Headache and nausea were the most frequently reported adverse reactions.",
  );

  const narrated = (points: readonly NarrativePoint[]): ScoredNarrative => ({
    narrative: {
      status: "narrated",
      points: [...points],
      model: "m",
      gatewayRequestId: null,
      generatedAt: "2026-08-26T10:00:00Z",
    },
    chunks: [A, B],
  });

  /*
    Sentences that stay inside their passage's vocabulary.

    Worth saying why they read a little flatly than they otherwise might: the
    first draft of these used "records jaundice as an uncommon occurrence" and
    "names headache and nausea as most frequent", and the unsupported-terms
    check flagged both — "uncommon", "occurrence" and "names" appear in neither
    passage. That is the check doing its job on the test data, and rewording
    was the honest response. It is also a fair demonstration of how tight the
    constraint on a grounded sentence really is.
  */
  const CLEAN: readonly NarrativePoint[] = [
    {
      chunkId: ChunkId.parse("ccds#1"),
      quotedSpan: "Jaundice has been reported rarely.",
      sentence: "The passage states jaundice has been reported rarely.",
    },
    {
      chunkId: ChunkId.parse("ccds#2"),
      quotedSpan: "Headache and nausea were the most frequently reported adverse reactions.",
      sentence: "The passage reports headache and nausea most frequently.",
    },
  ];

  it("scores a clean two-point narrative with no failures", () => {
    expect(scoreNarrative(narrated(CLEAN))).toHaveLength(0);
    expect(scoreNarrativeFaithfulness([narrated(CLEAN)]).score).toBe(1);
  });

  it("ignores an unavailable narrative, which claims nothing", () => {
    const failures = scoreNarrative({
      narrative: {
        status: "unavailable",
        reason: "no model is configured",
        model: null,
        gatewayRequestId: null,
        attemptedAt: "2026-08-26T10:00:00Z",
      },
      chunks: [A, B],
    });
    expect(failures).toHaveLength(0);
  });

  it("fails fatally on a fabricated span", () => {
    const failures = scoreNarrative(
      narrated([
        {
          chunkId: ChunkId.parse("ccds#1"),
          quotedSpan: "Fatal hepatic failure occurred in 3% of patients.",
          sentence: "The passage describes an outcome.",
        },
      ]),
    );
    expect(
      failures.some((f) => f.kind === "narrative_span_not_in_chunk" && f.fatal),
    ).toBe(true);
  });

  it("fails fatally on a point citing a passage that was not supplied", () => {
    const failures = scoreNarrative(
      narrated([
        {
          chunkId: ChunkId.parse("ccds#99"),
          quotedSpan: "Jaundice has been reported rarely.",
          sentence: "The passage records jaundice.",
        },
      ]),
    );
    expect(
      failures.some((f) => f.kind === "narrative_chunk_not_supplied" && f.fatal),
    ).toBe(true);
  });

  /*
    The split that makes this worth having separately from the rationale score.

    `verifyNarrative` drops any point whose sentence reaches a determination,
    so a surviving one cannot mean the model misbehaved — it can only mean the
    gate did not run. That is a correctness bug, so it is fatal here where the
    equivalent rationale failure is merely scored.
  */
  it("fails FATALLY on a surviving point that reaches a determination", () => {
    const failures = scoreNarrative(
      narrated([
        {
          chunkId: ChunkId.parse("ccds#1"),
          quotedSpan: "Jaundice has been reported rarely.",
          sentence: "This reaction is listed for the product.",
        },
      ]),
    );
    const failure = failures.find((f) => f.kind === "narrative_point_determines");
    expect(failure?.fatal).toBe(true);
  });

  it("fails FATALLY on a surviving point that recommends an action", () => {
    const failures = scoreNarrative(
      narrated([
        {
          chunkId: ChunkId.parse("ccds#1"),
          quotedSpan: "Jaundice has been reported rarely.",
          sentence: "The reviewer should note this passage.",
        },
      ]),
    );
    const failure = failures.find((f) => f.kind === "narrative_point_recommends");
    expect(failure?.fatal).toBe(true);
  });

  it("flags but does not fail two points citing one passage", () => {
    const first = CLEAN[0];
    if (first === undefined) throw new Error("fixture missing");
    const failures = scoreNarrative(
      narrated([
        first,
        {
          chunkId: ChunkId.parse("ccds#1"),
          quotedSpan: "Elevations in hepatic transaminases have been reported.",
          sentence: "Elevations in hepatic transaminases have been reported.",
        },
      ]),
    );
    const failure = failures.find((f) => f.kind === "narrative_duplicate_chunk");
    expect(failure).toBeDefined();
    expect(failure?.fatal).toBe(false);
  });

  it("leaves the reading score untouched", () => {
    // scoreFaithfulness knows nothing about narratives and must stay that way.
    expect(scoreFaithfulness([]).score).toBe(1);
  });
});
